paperConditionalSecondMoment.complete_declaration:
def paperConditionalSecondMoment (p h a x : ℝ) : ℝ :=
  selectionAverage p (fun selected ↦
    gaussianSecondMoment (x + selectedDrift p h (a * x) selected) (2 * h * p))

fullNoiseConditionalSecondMoment.complete_declaration:
def fullNoiseConditionalSecondMoment (p h a x : ℝ) : ℝ :=
  selectionAverage p (fun selected ↦
    gaussianSecondMoment (x + selectedDrift p h (a * x) selected) (2 * h))

joint.complete_declaration:
def joint {N dθ dx : ℕ} (i : Fin N) (z : State N dθ dx) : Joint dθ dx :=
  WithLp.toLp 2 (Sum.elim (fun j ↦ z (Sum.inl j))
    (fun j ↦ Real.sqrt N * z (Sum.inr (i, j))))

potential_strongConvex.statement:
theorem potential_strongConvex {N dθ dx : ℕ} {U : Fin N → Joint dθ dx → ℝ} {m : ℝ}
    (hU : ∀ i, StrongConvexOn Set.univ m (U i)) :
    StrongConvexOn Set.univ ((N : ℝ) * m) (@potential N dθ dx U)

jointCLM.complete_declaration:
def jointCLM {N dθ dx : ℕ} (i : Fin N) : State N dθ dx →L[ℝ] Joint dθ dx :=
  LinearMap.toContinuousLinearMap
    { toFun := joint i
      map_add' := joint_add i
      map_smul' := joint_smul i }

potential_differentiable.complete_declaration:
theorem potential_differentiable {N dθ dx : ℕ} {U : Fin N → Joint dθ dx → ℝ}
    (hU : ∀ i, Differentiable ℝ (U i)) : Differentiable ℝ (@potential N dθ dx U) := by
  exact Differentiable.fun_sum fun i _ ↦ (hU i).comp (jointCLM i).differentiable

potential_gradient_lipschitz.statement:
theorem potential_gradient_lipschitz {N dθ dx : ℕ} {U : Fin N → Joint dθ dx → ℝ} {L : ℝ≥0}
    (hU : ∀ i, Differentiable ℝ (U i)) (hLip : ∀ i, LipschitzWith L (gradient (U i))) :
    LipschitzWith ((N : ℝ≥0) * L) (gradient (@potential N dθ dx U))

meanForce.complete_declaration:
def meanForce {N dθ dx : ℕ} (U : Fin N → Joint dθ dx → ℝ)
    (z : State N dθ dx) : State N dθ dx :=
  (N : ℝ)⁻¹ • gradient (potential U) z

fullBatchStep.complete_declaration:
def fullBatchStep {N dθ dx : ℕ} (U : Fin N → Joint dθ dx → ℝ) (h : ℝ)
    (z ξ : State N dθ dx) : State N dθ dx :=
  LatentDiffusion.eulerStep (meanForce U) h z (Real.sqrt (2 * h / N) • ξ)

liftedForce_coe.statement:
theorem liftedForce_coe {F : E → E} {m : ℝ} {L : ℝ≥0}
    (hF : ForceRegularity F m L) (X : Lp E 2 P) :
    liftedForce P hF X =ᵐ[P] fun ω ↦ F (X ω)

parameterOutput.complete_declaration:
def parameterOutput :
    Lp (Cloud.State K dθ dz) 2 P →L[ℝ] Lp (EuclideanSpace ℝ (Fin dθ)) 2 P :=
  (@IPLA.parameterCLM K dθ dz).compLpL 2 P

averageMarginalPotential.complete_declaration:
def averageMarginalPotential (U : Fin M → IPLA.Joint dθ dz → ℝ)
    (θ : EuclideanSpace ℝ (Fin dθ)) : ℝ :=
  (M : ℝ)⁻¹ * ∑ i, IPLA.marginalPotential (U i) θ

batchAverage.complete_declaration:
def batchAverage {M : ℕ} (B : ℕ) (batch : Ω → Finset (Fin M))
    (g : Fin M → H) (ω : Ω) : H :=
  (1 / (B : ℝ)) • ∑ i, inclusion batch ω i • g i

noisyEulerTrajectory.complete_declaration:
def noisyEulerTrajectory {Ω : Type*} (F : H → H) (h : ℝ)
    (ξ ζ : ℕ → Ω → H) (x₀ : Ω → H) (n : ℕ) (ω : Ω) : H :=
  eulerTrajectory F h (fun k ↦ ξ k ω + h • ζ k ω) (x₀ ω) n

ProductDensityChart.energy.complete_declaration:
def ProductDensityChart.energy (x : X) : ℝ :=
  (M : ℝ)⁻¹ * ∑ i, SourceCalculus.densityFreeEnergy volume
    ((D.chart i).density x) (U i (D.parameter x))

physicalParticleCLM.complete_declaration:
def physicalParticleCLM (i : Fin K) :
    Cloud.State K dθ dz →L[ℝ] EuclideanSpace ℝ (Fin dz) :=
  LinearMap.toContinuousLinearMap
    { toFun := fun x ↦ Real.sqrt (K : ℝ) • Cloud.block x i
      map_add' := by intro x y; ext j; simp [Cloud.block, mul_add]
      map_smul' := by intro c x; ext j; simp [Cloud.block, mul_left_comm] }

fluxDivergence.complete_declaration:
def fluxDivergence (V : E → E) (x : E) : ℝ :=
  ∑ i : Fin (Module.finrank ℝ E),
    fderiv ℝ (fluxComponent V i) x (stdOrthonormalBasis ℝ E i)

averagedParameterForce.complete_declaration:
def averagedParameterForce (ν : Measure E) (q : Fin M → E → ℝ)
    (U : Fin M → A → E → ℝ) (a : A) : A :=
  (M : ℝ)⁻¹ • ∑ i, parameterForce ν (q i) (U i) a

normalizedDensityEnergy.complete_declaration:
def normalizedDensityEnergy (ν : Measure E) (q : Fin M → E → ℝ)
    (U : Fin M → A → E → ℝ) (a : A) : ℝ :=
  (M : ℝ)⁻¹ * ∑ i, SourceCalculus.densityFreeEnergy ν (q i) (U i a)

force.complete_declaration:
def force {F : Cloud.State K dθ dz → Cloud.State K dθ dz} {m : ℝ} {L : ℝ≥0}
    (hF : ForceRegularity F m L) (X : Lp (Cloud.State K dθ dz) 2 P) :=
  averageCLM P (liftedForce P hF X)

force_lipschitz.statement:
theorem force_lipschitz {F : Cloud.State K dθ dz → Cloud.State K dθ dz}
    {m : ℝ} {L : ℝ≥0} (hF : ForceRegularity F m L) :
    LipschitzWith (2*L) (force P hF)

OptimalAnchor.distance_eq.statement:
theorem OptimalAnchor.distance_eq {Y : Lp E 2 P} {target : Measure E}
    (D : OptimalAnchor P Y target) :
    ULA.wasserstein2Real (P.map Y) target = ‖Y - D.value‖

latentInsert.complete_declaration:
def latentInsert : EuclideanSpace ℝ (Fin dz) →L[ℝ] IPLA.Joint dθ dz :=
  LinearMap.toContinuousLinearMap
    { toFun := fun z ↦ IPLA.pair 0 z
      map_add' := by intro x y; ext j; cases j <;> simp [IPLA.pair]
      map_smul' := by intro c x; ext j; cases j <;> simp [IPLA.pair] }

headInsert.complete_declaration:
def headInsert {d : ℕ} {J : Type*} [Fintype J] :
    Parameter d →L[ℝ] EuclideanSpace ℝ (Fin d ⊕ J) :=
  LinearMap.toContinuousLinearMap
    { toFun := fun a => WithLp.toLp 2 (Sum.elim a (fun _ => 0))
      map_add' := by intro a b; ext j; cases j <;> simp
      map_smul' := by intro c a; ext j; cases j <;> simp }

headExtract.complete_declaration:
def headExtract {d : ℕ} {J : Type*} [Fintype J] :
    EuclideanSpace ℝ (Fin d ⊕ J) →L[ℝ] Parameter d :=
  LinearMap.toContinuousLinearMap
    { toFun := fun x => WithLp.toLp 2 (fun j => x (Sum.inl j))
      map_add' := by intro a b; rfl
      map_smul' := by intro c a; rfl }

tailMask.complete_declaration:
def tailMask {d : ℕ} {J : Type*} [Fintype J] :
    EuclideanSpace ℝ (Fin d ⊕ J) →L[ℝ] EuclideanSpace ℝ (Fin d ⊕ J) :=
  ContinuousLinearMap.id ℝ _ - headInsert.comp headExtract

parameterScore.complete_declaration:
def parameterScore (U : Fin K → Cloud.Joint dθ dz → ℝ) (i : Fin K)
    (x : Cloud.State K dθ dz) : Cloud.State K dθ dz :=
  headInsert (headExtract (gradient (U i) (Cloud.joint i x)))

