theorem parameterOutput_frozen_zero {F : Cloud.State K dθ dz → Cloud.State K dθ dz}
    {m : ℝ} {L : ℝ≥0} (hF : ForceRegularity F m L) (X : Lp (Cloud.State K dθ dz) 2 P) :
    parameterOutput P (frozenForce P hF X) = 0

