packLp.complete_declaration:
def packLp (astar : Parameter dθ) (Z : Lp (Latent K dz) 2 P) :
    Lp (Cloud.State K dθ dz) 2 P :=
  constantL2 P (headInsert astar) + (Real.sqrt (K : ℝ))⁻¹ • tailInsert.compLpL 2 P Z

tailExtract.complete_declaration:
def tailExtract : Cloud.State K dθ dz →L[ℝ] Latent K dz :=
  LinearMap.toContinuousLinearMap
    { toFun := fun x => WithLp.toLp 2 (fun j => x (Sum.inr j))
      map_add' := by intro a b; rfl
      map_smul' := by intro c a; rfl }

frozenPotential.complete_declaration:
def frozenPotential (U : Fin K → Cloud.Joint dθ dz → ℝ)
    (astar : Parameter dθ) (z : Latent K dz) : ℝ :=
  Cloud.potential U (pack astar z)

freeEnergy.complete_declaration:
def freeEnergy (D : RegularDisplacement ν μ d) (U : P → Z → ℝ)
    (p₀ p₁ : P) (s : ℝ) : ℝ :=
  D.entropy s + ∫ z, U (parameterInterpolate p₀ p₁ s) z ∂D.law s

displacementField.complete_declaration:
def displacementField (D : RegularDisplacement (volume : Measure Z) μ d)
    (p₀ p₁ : P) (z : Z) : Joint (P := P) (Z := Z) :=
  PBGSO.ProductTransport.embed (p₁ - p₀) (D.transport z - z)

latentScore.complete_declaration:
def latentScore (m : Fin M) (z : Z) : Z :=
  (R.potential_gradient m z).snd +
    gradient (fun z ↦ Real.log ((R.displacement m).density 0 z)) z

IsConstantSpeedGeodesic.complete_declaration:
def IsConstantSpeedGeodesic (q : ℝ → Measure Z) : Prop :=
  ∀ s ∈ Icc (0 : ℝ) 1, ∀ t ∈ Icc (0 : ℝ) 1, s ≤ t →
    ULA.wasserstein2Real (q s) (q t) = (t - s) * ULA.wasserstein2Real (q 0) (q 1)

productDistance.complete_declaration:
def productDistance (a : ℝ → P) (q : ℝ → Fin M → Measure Z) (s t : ℝ) : ℝ :=
  Real.sqrt (‖a s - a t‖ ^ 2 + (M : ℝ)⁻¹ * ∑ m,
    ULA.wasserstein2Real (q s m) (q t m) ^ 2)

IsProductGeodesic.complete_declaration:
def IsProductGeodesic (a : ℝ → P) (q : ℝ → Fin M → Measure Z) : Prop :=
  ∀ s ∈ Icc (0 : ℝ) 1, ∀ t ∈ Icc (0 : ℝ) 1, s ≤ t →
    productDistance a q s t = (t - s) * productDistance a q 0 1

DensityModel.trialDensity.complete_declaration:
def DensityModel.trialDensity (D : DensityModel A Z M ν) (a : A)
    (q : Fin M → ProbabilityMeasure Z) (i : Fin M) : Z → ℝ :=
  Density.trialDensity (D.density a i) (relativeDensity (D.posterior a i) (q i)) (D.mass a i)

freeEnergy.complete_declaration:
def freeEnergy (a : A) (q : Fin M → ProbabilityMeasure Z) : ℝ :=
  -P.logEvidence a + (M : ℝ)⁻¹ *
    ∑ m, (InformationTheory.klDiv (q m : Measure Z) (P.posterior a m : Measure Z)).toReal
